function rfWebsiteSeedDocuments_(){return [{"kind":"page","id":"home","name":"Trang chủ","blocks":[{"id":"hero","visible":true,"title":"Một khoảng thiên nhiên.\nMột dấu ấn riêng.","text":"Thiên nhiên, được tinh tuyển.","caption":"","image":"/images/rf/brand-banners.png"},{"id":"brand","visible":true,"image":"/images/rf/brand-banners.png"},{"id":"studio","visible":true,"title":"Từ nguyên liệu tự nhiên\nđến một thế giới riêng.","text":"Chúng tôi chế tác thủ công từng chi tiết, để mang thiên nhiên vào không gian sống của bạn."},{"id":"collection","visible":true,"title":"Được tạo nên bằng đôi tay.","image":"/images/brand/rf-limited-black.jpg"},{"id":"creatures","visible":true,"title":"Linh Thú.","text":"Những hình dáng khác của lũa.","image":"/images/rf/brand-banners.png"},{"id":"crafted","visible":true,"title":"Thiên nhiên, được tinh tuyển.","text":"Made by hand. Shaped by nature.","image":"/images/rf/workbench.png"},{"id":"journal","visible":true,"title":"Góc thủy sinh"},{"id":"closing","visible":true,"title":"Cùng tạo nên góc thiên nhiên của bạn.","text":"BẠN ĐANG HÌNH DUNG MỘT BỂ THỦY SINH?"}]},{"kind":"post","id":"rf-biotop","title":"Ba hướng bố cục Biotop từ RF","name":"Ba hướng bố cục Biotop từ RF","description":"","body":"Đá cuội, Blackwater và lũa Nature: những gợi ý từ các mẫu bể RF đã thực hiện.\n\nBiotop đá cuội Vân Mây dùng đá làm điểm tựa cho bố cục. Rêu Java, ráy và các cây hậu cảnh dễ chăm sóc là những gợi ý trong bài chia sẻ của RF.\n\nVới Blackwater, bố cục lấy cảm hứng từ đáy suối: lá bàng khô, vỏ cây và các chi tiết tự nhiên nằm trên nền sạn. Màu sắc và vật liệu tạo nên một không gian khác với bể đá cuội sáng màu.\n\nHướng Nature khai thác hình dáng của lũa san cành. Có thể bắt đầu bằng bộ khung lũa, sau đó chọn cây và khoảng trống theo không gian bể.\n\nXem bài gốc để tham khảo ảnh từng bố cục và các gợi ý cụ thể từ RF.","image":"/images/source/biotop.webp"},{"kind":"post","id":"rf-forest-kit","title":"Rừng ver.16: bắt đầu từ một bộ khung","name":"Rừng ver.16: bắt đầu từ một bộ khung","description":"","body":"Tìm hiểu cách RF giới thiệu bộ kit và các module hardscape cho bố cục rừng.\n\nTrong bài giới thiệu Rừng ver.16, RF trình bày một hướng tiếp cận theo module: bộ khung lũa được ghép trước để người chơi tiếp tục sắp xếp và trồng cây trong bể của mình.\n\nBài viết minh họa nhóm vật liệu nền, dụng cụ cắt tỉa và mã QR hướng dẫn trên bao bì. Các phần này phục vụ quá trình tự setup, thay vì bắt đầu bằng việc tìm từng nhánh lũa riêng lẻ.\n\nẢnh bộ kit trong bài giúp hình dung cách phối hợp vật liệu và hình dáng rừng. Khi chọn sản phẩm, hãy trao đổi với RF về phiên bản, kích thước và thành phần bộ kit phù hợp; không mặc định mọi mẫu Rừng đều có cùng phụ kiện.\n\nXem bài gốc để khám phá các góc ảnh và thông tin bộ kit RF giới thiệu.","image":"/images/black-covers/52f9478c73483e3553e0.jpg"},{"kind":"post","id":"rf-rhino","title":"Tê Giác: tạo hình từ những nhánh lũa","name":"Tê Giác: tạo hình từ những nhánh lũa","description":"","body":"Một góc nhìn về cách ghép lũa và gợi ý trồng cây quanh tác phẩm Tê Giác của RF.\n\nLayout Tê Giác được RF giới thiệu như một tác phẩm tạo hình bằng lũa ghép thủ công. Hướng và bề mặt các mảnh gỗ cùng tạo nên dáng đứng, phần đầu và cấu trúc của thân.\n\nBài nguồn gợi ý đặt tác phẩm trong bố cục rừng hoặc bể bán cạn. Rêu, Bucephalandra và ráy nhỏ có thể được điểm vào các khe của lũa để bổ sung lớp cây xanh.\n\nÁnh sáng tập trung vào phần đầu là một gợi ý để làm rõ hình dáng tác phẩm. Khi sắp xếp trong bể, cần chọn kích thước và khoảng trống phù hợp thay vì chỉ nhìn hình từ một góc.\n\nXem bài gốc để tham khảo các góc ảnh Tê Giác và trao đổi với RF về bố cục của bạn.","image":"/images/black-covers/231beab5e3edede7cb86.jpg"}];}
